cat > /tmp/run.sh <<'SH'
#!/bin/bash
E=/workspace/dataset/test16_executable
while IFS= read -r line; do
  [ -z "$line" ] && continue
  inp=$(printf '%b' "$line")
  echo "### IN=<$line>"
  out=$("$E" --a "$inp" 2>&1); rc=$?
  echo "RC=$rc"
  printf '%s' "$out" | cat -A | sed 's/^/  |/'
done
SH
chmod +x /tmp/run.sh
